import { readFile, writeFile } from 'node:fs/promises';

const source = new URL('../frontend/shared/mfm.css', import.meta.url);
const target = new URL('../frontend/shared/mfm-styles.ts', import.meta.url);
const css = await readFile(source, 'utf8');
await writeFile(target, `/*
 * SPDX-FileCopyrightText: syuilo and misskey-project
 * SPDX-License-Identifier: AGPL-3.0-only
 */

// Generated by markup/scripts/generate-mfm-styles.mjs from mfm.css. Do not edit.
// Embed CSS in the Node bundle without depending on asset-copy paths at runtime.
// eslint-disable-next-line @stylistic/quotes
export const mfmStyles = ${JSON.stringify(css)};
`);
